import java.util.*;

class Solution {
  public int maxSumSubmatrix(int[][] matrix, int k) {
    int rows = matrix.length, cols = matrix[0].length, best = Integer.MIN_VALUE;
    for (int top = 0; top < rows; top++) {
      int[] colSums = new int[cols];
      for (int bottom = top; bottom < rows; bottom++) {
        for (int c = 0; c < cols; c++) colSums[c] += matrix[bottom][c];
        // largest subarray sum <= k: for each prefix p, smallest earlier prefix >= p - k
        TreeSet<Integer> prefixes = new TreeSet<>();
        prefixes.add(0);
        int prefix = 0;
        for (int v : colSums) {
          prefix += v;
          Integer ceil = prefixes.ceiling(prefix - k);
          if (ceil != null) best = Math.max(best, prefix - ceil);
          prefixes.add(prefix);
        }
        if (best == k) return k;
      }
    }
    return best;
  }
}
